{
 "project": "Qhedache, Version 1.0",
 "meeting": "1 of 1 (kickoff)",
 "participants": [
  "Analyst",
  "Client",
  "EndUser",
  "TechLead"
 ],
 "previous_turns_for_context_only": [],
 "turns": [
  {
   "id": "M1:T1",
   "speaker": "Analyst",
   "act": "open",
   "guide": "Analyst opens the meeting about Qhedache (meeting 1 of 1, kickoff)."
  },
  {
   "id": "M1:T2",
   "speaker": "Client",
   "act": "context",
   "guide": "Client gives the project background below, in their own words.",
   "content": [
    {
     "text": "This specifications establishes the requirements for the product named Qheadache. The intended audience is the analyst, programmer and tester of Qheadache. The product is a computerized game that displays an interface used to solve a specific headache.",
     "role": "background"
    }
   ]
  },
  {
   "id": "M1:T3",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'external interfaces' and asks about it."
  },
  {
   "id": "M1:T4",
   "speaker": "TechLead",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The hardware and operating system must provide an 800x600 screen resolution.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T5",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'main window' and asks about it."
  },
  {
   "id": "M1:T6",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "The main window shall provide the following parts : A board, see chapter 3.2.1.1; a menu bar, see chapter 3.2.5.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T7",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'block selection' and asks about it."
  },
  {
   "id": "M1:T8",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Block selection. Input: Leftclicked down on a block. Processing: The game state becomes \"Block deplacement\".",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T9",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'block deselection' and asks about it."
  },
  {
   "id": "M1:T10",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Block deselection. Input: Leftclicked up on a selected block. Processing: The game state becomes \"Block selection\".",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T11",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'block movement' and asks about it."
  },
  {
   "id": "M1:T12",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Block movement. Input: Mouse movement during the \"Block movement\" state. Processing: The selected block follows the mouse movement without overlapp the other blocks and exit of the game zone. The selected block can' mt ove near other blocks at least 0.05x from the others blocks.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T13",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'undo action' and asks about it."
  },
  {
   "id": "M1:T14",
   "speaker": "EndUser",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Undo Action. Input: Menu selection. Processing: The game displays the block positions at the places where they were before the last movement. This action is consider like a movement. The \"undo\" action is unvailable if there was no previous movement. Output: New game board display.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T15",
   "speaker": "Analyst",
   "act": "backchannel",
   "guide": "Short acknowledgment while listening (1-3 words)."
  },
  {
   "id": "M1:T16",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'redo action' and asks about it."
  },
  {
   "id": "M1:T17",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Redo Action. Input: Menu selection. Processing: The game displays the block positions at the places where they were before the last movement was canceled. This action is consider like a movement. The redo action is unvailable, if the previous action wasn't a n \"undo\" action. Output: New game board display.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T18",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'end of the game' and asks about it."
  },
  {
   "id": "M1:T19",
   "speaker": "Client",
   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "End of the game. Input: The great square is moved at the bottom of the board. Processing: All the player statistics are freezed. Output: If the number of block movements of the current player is lower than the highest number of block movement recorded in the statistic file, the The \"Finish Window with Statistcs\" is displayed, see chapter 3.2.2.2. If not the \"Simple finish Window\" is displayed, see chapter 3.2.2.3.",
     "role": "statement"
    }
   ]
  },
  {
   "id": "M1:T20",
   "speaker": "Analyst",
   "act": "ask_topic",
   "guide": "Analyst moves the discussion to the topic 'finish window with statistics' and asks about it."
  }
 ]
}
